type NavIconName = "courts" | "my-courts" | "tasks" | "rankings" | "wallet";
function NavIcon({name}:{name:NavIconName}) {
 const p={width:23,height:23,viewBox:"0 0 24 24",fill:"none",stroke:"currentColor",strokeWidth:1.8,strokeLinecap:"round" as const,strokeLinejoin:"round" as const,"aria-hidden":true as const};
 if(name==="courts")return <svg {...p}><path d="M3 7.5 12 3l9 4.5v9L12 21l-9-4.5z"/><path d="m3.5 7.8 8.5 4.4 8.5-4.4M12 12.2V21M8 5l8.5 4.3M16 5 7.5 9.3"/></svg>;
 if(name==="my-courts")return <svg {...p}><path d="M7 4.5h10a2 2 0 0 1 2 2v14H5v-14a2 2 0 0 1 2-2Z"/><path d="M9 4.5v-2h6v2M8.5 10h7M8.5 14h7M8.5 18h4"/></svg>;
 if(name==="tasks")return <svg {...p}><rect x="4" y="3.5" width="16" height="18" rx="2.2"/><path d="M8 8.5h.01M11 8.5h5M8 13h.01M11 13h5M8 17.5l1.5 1.5L12 16.5M14 18h2"/></svg>;
 if(name==="rankings")return <svg {...p}><path d="M8 4h8v5a4 4 0 0 1-8 0V4Z"/><path d="M8 6H4v2a4 4 0 0 0 4 4M16 6h4v2a4 4 0 0 1-4 4M12 13v4M8 21h8M9 17h6"/></svg>;
 return <svg {...p}><rect x="3" y="6" width="18" height="14" rx="2.3"/><path d="M3 9h18M16 14h2.5M7 6V4.5A1.5 1.5 0 0 1 8.5 3h7A1.5 1.5 0 0 1 17 4.5V6"/></svg>;
}
type CheckinDay={date:string;checked_in:boolean};
type CheckinState={today:string;days:CheckinDay[];streak:number;total_checkins:number;checked_in_today:boolean};

type Tab = "Courts" | "My Courts" | "Tasks" | "Rankings" | "Wallet";
const onboardingStories=[
 {title:"Welcome to the football courtroom.",body:"Settle This! is where football fans take a position on the moments, decisions and debates that divide the game. Bring your football knowledge, explain your thinking and make your case.",label:"THE COURTROOM",detail:"A Court is a structured football debate with two clear positions and a defined resolution."},
 {title:"Discover the Courts.",body:"Regular Courts focus on one football question and have a fixed CT entry and a published SETHIS reward for each qualifying winner. Pool Courts invite fans to stake CT on either side of a debate and share a published SETHIS prize if their side wins.",label:"TWO WAYS TO TAKE PART",detail:"Always check the entry, minimum stake, deadline and reward displayed on each Court."},
 {title:"Choose your side.",body:"Every Court presents Side A and Side B. Read both positions, review the case context and choose the side you genuinely support. Your selection records your position in that Court.",label:"SIDE A / SIDE B",detail:"An invite link may point to a side, but it never chooses or stakes on behalf of the person opening it."},
 {title:"Understand Court Tokens (CT).",body:"CT is the platform currency used to enter Regular Courts and stake in Pool Courts. The standard Regular Court entry is 500 CT, while each Pool Court shows its own minimum stake. Your available CT balance is shown in the header and Wallet.",label:"CT = COURT ENTRY",detail:"CT is not SETHIS. Your welcome gift gives you 3,500 CT to start participating."},
 {title:"Meet SETHIS.",body:"SETHIS is the platform's main reward token. Regular Court winners receive the fixed reward displayed on that Court. Pool Court winners share its published prize in proportion to their winning-side CT stakes.",label:"SETHIS = REWARD TOKEN",detail:"CT is used to participate; SETHIS is credited as a qualifying reward. They are separate balances."},
 {title:"Make your case. Respect the game.",body:"After joining, add your argument, reply to other fans and use reactions to show agreement, disagreement or appreciation for useful insight. Support claims with credible evidence and keep debate respectful.",label:"ARGUMENTS · REPLIES · REACTIONS",detail:"Crowd reactions show community sentiment. They do not decide the official verdict."},
 {title:"The verdict and your wallet.",body:"Courts close at their published deadline and are resolved using the stated criteria and evidence. The editorial adjudication determines the official outcome. Eligible rewards and wallet activity are recorded so you can review your history.",label:"CLEAR RULES. RECORDED OUTCOMES.",detail:"Your Wallet separates CT and SETHIS and displays verified credits and debits."}
];
const crest = (id: number) => `https://media.api-sports.io/football/teams/${id}.png`;
function Brand() { return <a className="brand" href="#" aria-label="Settle This home"><BrandMark className="brand-emblem"/><span className="brand-wordmark"><b>SETTLE</b><i>THIS!</i></span></a>; }
function Team({ id, name }: { id: number; name: string }) { return <span className="team"><span className="crest"><img src={crest(id)} alt="" /></span><b>{name}</b></span>; }
type CourtFeedItem = { id:string; title:string; category:string; competition?:string|null; home_team?:string|null; away_team?:string|null; home_team_crest?:string|null; away_team_crest?:string|null; match_status?:string|null; live_minute?:number|null; home_score?:number|null; away_score?:number|null; lineup_status?:string|null; home_lineup_json?:string|null; away_lineup_json?:string|null; hero_image_url?:string|null; image_alt?:string|null; evidence_url?:string|null; incident_minute?:number|null; incident_context:string; side_a_label:string; side_b_label:string; entry_ct:number; winner_reward_sethis:number; status:string; closes_at?:string|null; side_a_count: number; side_b_count: number };
type MyCourtItem = { id:string; title:string; category:string; competition?:string|null; home_team?:string|null; away_team?:string|null; home_team_crest?:string|null; away_team_crest?:string|null; match_date?:string|null; incident_minute?:number|null; incident_context?:string; evidence_url?:string|null; home_score?:number|null; away_score?:number|null; side_a_label:string; side_b_label:string; status:string; closes_at?:string|null; side:"A"|"B"; entry_ct:number; winner_reward_sethis:number; winner_side?:string|null; verdict?:string|null; adjudication_notes?:string|null; settled_at?:string|null; participation_status:string; joined_at:string };
type PoolMarketData = { id:string; title:string; prize_amount:number; minimum_stake_ct:number; duration_days:number; status:string; reserve_status?:string; opens_at?:string|null; closes_at?:string|null; side_a_label?:string; side_b_label?:string; side_a_stake:number; side_b_stake:number; side_a_count: number; side_b_count: number };
type AppNotification = {id:string;type:string;title:string;body:string;reference_id:string|null;created_at:string;read_at:string|null};
