 {task_key:"facebook_follow",title:"Follow us on Facebook",description:"Follow the official Settle This! Facebook page.",reward_token:"SETHIS",reward_amount:100,destination_url:null,verification_method:"manual",claim_status:null},
 {task_key:"whatsapp_community",title:"Join our WhatsApp community",description:"Join the official Settle This! WhatsApp community.",reward_token:"SETHIS",reward_amount:70,destination_url:null,verification_method:"manual",claim_status:null},
 {task_key:"invite_three",title:"Invite 3 football friends",description:"Earn the milestone reward when three invited friends complete onboarding.",reward_token:"SETHIS",reward_amount:500,destination_url:null,verification_method:"referral",claim_status:null}
